#!/usr/bin/env python3
"""Ripristina il progetto ORIGINI da un archivio incorporato (nessuna rete)."""
from pathlib import Path
from io import BytesIO
import base64, lzma, tarfile

PAYLOAD = """"""
with tarfile.open(fileobj=BytesIO(lzma.decompress(base64.b64decode(PAYLOAD))), mode="r:") as z:
    target = Path.cwd().resolve()
    for item in z.getmembers():
        path = (target / item.name).resolve()
        if path != target and target not in path.parents:
            raise RuntimeError("Path non consentito: " + item.name)
    z.extractall(path=target, filter="data")
print("ORIGINI: sorgenti ripristinati nella cartella corrente")